    'RegistrationText'=>'A regisztrált SimpleRisk példányok azonnali hozzáférést kapnak a frissítés (Upgrade) és a Secure Controls Framework (SCF) Extrákhoz.  A frissítés Extra lehetővé teszi a SimpleRisk példány biztonsági mentését és frissítését egyetlen kattintással.  A Secure Controls Framework (SCF) Extra egy közös kontroll-keretrendszert biztosít, amely integrálva van a SimpleRisk governance funkcióiba.  A SimpleRisk regisztrálásakor a regisztrációs információk egy, a SimpleRisk által üzemeltetett szerverre kerülnek elküldésre.  A megadott regisztrációs információkat a SimpleRisk arra használja, hogy értesítse az ügyfeleket az új kiadásokról és a biztonsági frissítésekről.  A SimpleRisk regisztrálásával feliratkozik marketingkommunikációnkra, de ezt bármikor leiratkozhat az ezekben a közleményekben található leiratkozási hivatkozással.  A SimpleRisk tiszteletben tartja ügyfelei magánéletét, és a SimpleRisk regisztrációs folyamat során megadott információkat soha nem adjuk el harmadik félnek.',
