    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Rendszerszintű beállítások konfigurálása: alap URL, biztonság, alapértelmezett nyelv, időzóna, a kockázatpontozás alapértelmezései és egyebek.',
    'SettingsPreferencesDesc'             => 'Alapértelmezett értékek és viselkedési preferenciák a SimpleRisk egészében: nyelv, időzóna, audit állapotok, kockázatleképezési követelmények, felhasználói felület viselkedését szabályozó kapcsolók és hasonlók.',
    'SettingsFileUploadDesc'              => 'Engedélyezett fájlfeltöltési típusok és méretkorlátok a különböző fájlmelléklet-mezőkre vonatkozóan.',
    'SettingsMailDesc'                    => 'SMTP-konfiguráció a kimenő e-mail értesítésekhez, beleértve az átvitelt, a hosztot, a hitelesítést és a válaszcímet.',
    'SettingsBackupsDesc'                 => 'Konfigurálja a biztonsági mentések megőrzését, ütemezését és letöltési hivatkozásait a SimpleRisk adatbázis-mentésekhez.',
    'SettingsSecurityDesc'                => 'Hitelesítési, munkamenet-, jelszóházirend-, alap URL- és API-biztonsági beállítások.',
    'SettingsLoggingDesc'                 => 'Hibakeresési és auditnaplózási konfiguráció: naplózási szintek, megőrzés és a naplófájlok helye.',
    'HealthCheckDesc'                     => 'A rendszerállapot diagnosztizálása: PHP verzió, kiterjesztések, fájlengedélyek, adatbázis-kapcsolat, cron ütemezés és az Extra aktiválások.',
    'AnnouncementsDesc'                   => 'Írjon és kezeljen minden felhasználó számára látható bannerbejelentéseket.',
    'RegisterAndUpgradeDesc'              => 'Regisztrálja a SimpleRisk telepítését, adja meg vagy újítsa meg az előfizetési kulcsot, és indítsa el az egykattintásos Core/Extra frissítéseket.',
    'QueueMonitorDesc'                    => 'Vizsgálja meg a háttérben futó feladatok várólistáját: függőben lévő, folyamatban lévő és sikertelen feladatok.',
    'ExtrasDesc'                          => 'A SimpleRisk Extrák (fizetős bővítmények) aktiválása, deaktiválása és konfigurálása.',
    'ArtificialIntelligenceExtraDesc'     => 'A Mesterséges Intelligencia Extra továbbfejlesztett kockázatelemzést (beleértve a FAIR-értékeléseket) és testreszabott dokumentációt biztosít.',
    'CustomizationExtraDesc'              => 'A Testreszabási extra lehetővé teszi különböző típusú mezők hozzáadását és eltávolítását, valamint egyéni oldalsablonok dinamikus létrehozását.',
    'NotificationExtraDesc'               => 'Az E-mail értesítés Extra lehetővé teszi, hogy a SimpleRisk e-mail értesítéseket küldjön, amikor kockázatokat nyújtanak be, módosítanak, vagy egyéb műveletet hajtanak végre rajtuk. Ez az Extra ütemezett szkriptként is hozzáadható, hogy rendszeres emlékeztetőket küldjön, amikor a kockázatok készen állnak a vezetői felülvizsgálatra. A SimpleRisk Core termékben ezen Extra nélkül az eszközön kívülre nem kerül értesítés kommunikálásra.',
    'VulnerabilityManagementExtraDesc'    => 'A Sebezhetőségkezelés Extra lehetővé teszi az ügyfelek számára, hogy a SimpleRisk példányukat integrálják a Qualys, a Tenable.io vagy a Rapid7 Nexpose/InsightVM rendszerrel, és eszköz- és sebezhetőségi adatokat is importáljanak a SimpleRisk-be. Ezt követően kiválaszthatja, mely helyszíneket kívánja lefedni, meghatározhatja, mely sebezhetőségi pontszámok kerüljenek importálásra, és szűrheti, mely sebezhetőségekből legyen kockázat a nyomon követésükhöz.',
    'IncidentManagementExtraDesc'         => 'Az Incidenskezelés Extra a NIST 800-61 Computer Security Incident Handling Guide-on alapul, és incidenskezelési képességeket biztosít a SimpleRisk rendszeren belül.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'A SimpleRisk terminológia (kockázat, eszköz, keretrendszer stb.) átnevezése a teljes felületen.',
    'RiskConfigurationDesc'               => 'Kockázatpontozási szabályok konfigurálása: szintek, kockázati étvágy, SLA-küszöbértékek és a klasszikus/hozzájáruló kockázati képletek.',
    'RiskAndThreatCatalogDesc'            => 'Karbantartja a legördülő menükben használt kockázati és fenyegetési értékek katalógusát.',
    'AddAndRemoveValuesDesc'              => 'Kezelje a kockázati mezők legördülő értékeit: hely, forrás, kategória, csapat, technológia és egyebek.',
    'AssetValuationDesc'                  => 'Konfigurálja az eszközértékelési skálát és az eszközönkénti értékelési felülbírálásokat.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Felhasználók hozzáadása, szerkesztése, letiltása és visszaállítása; jelszóirányelvek kezelése.',
    'RoleManagementDesc'                  => 'Szerepkörök és az egyes szerepkörök által megadott engedélyek meghatározása.',
    'TeamManagementDesc'                  => 'Rekordok láthatóságának szűréséhez használt csapatok létrehozása és kezelése.',
    'SeparationExtraDesc'                 => 'A Csapatalapú Elkülönítés Extra a kockázatok megtekintését csak azokra a felhasználókra korlátozza, akik a kockázathoz rendelt csapat tagjai. A SimpleRisk Core termékben, ezen Extra nélkül, minden felhasználó láthatja az összes kockázatot.',
    'CustomAuthenticationExtraDesc'       => 'Az Egyéni hitelesítés Extra támogatást nyújt az Active Directory és a SAML hitelesítéshez. A SimpleRisk Core termékben ezen Extra nélkül az egyetlen lehetőség új felhasználók létrehozása a SimpleRisk identitástárában.',
    'EncryptionExtraDesc'                 => 'A Titkosított adatbázis Extra egy véletlenszerű, AES-256 bites titkosítási kulcsot hoz létre, majd ezzel titkosítja az érzékeny szövegeket, mielőtt azokat beszúrná a SimpleRisk adatbázisba. Ez megakadályozza, hogy bárki megtekinthesse vagy módosíthassa az adatokat a SimpleRisk alkalmazás közvetlen használata nélkül.',
    'OrganizationManagementDesc'          => 'A Szervezeti hierarchia Extra lehetővé teszi több üzleti egység meghatározását, amelyek tetszőleges számú csapatot tartalmazhatnak. A felhasználók ezután egy vagy több csapathoz rendelhetők a különböző üzleti egységeken belül. Ez befolyásolja, hogy a felhasználó mely csapatokat, felhasználókat és eszközöket láthatja és használhatja, amelyekhez nem kapcsolódik.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Kockázatok tömeges törlése. Használja mértékkel – a törlések véglegesek.',
    'AuditTrailDesc'                      => 'A felhasználói műveletek rendszer-auditnaplójának keresése és exportálása.',
    'ImportExportExtraDesc'               => 'Az Import-Export Extra lehetővé teszi adatok importálását a SimpleRisk-be egy CSV fájl mezőinek a SimpleRisk adatbázis mezőihez való leképezésével. Felhasználható audit eredmények importálására külső gyártótól származó táblázatból, más eszközből származó sebezhetőségi vizsgálati eredmények importálására, eszközök importálására a CMDB-ből és egyebekre. Az Extra lehetővé teszi továbbá CSV fájlok exportálását a SimpleRisk-ből, amelyek kockázatokat, mitigációkat, felülvizsgálatokat vagy mindhárom kombinált jelentését tartalmazzák.',
    'JiraExtraDesc'                       => 'A Jira integráció Extra lehetővé teszi a felhasználók számára a kétirányú integrációt egy Jira példánnyal. Lehetővé teszi a kockázatok Jira-hibajegyekhez kapcsolását, valamint adataik, állapotuk és megjegyzéseik szinkronizálását.',
    'APIExtraDesc'                        => 'Az API Extra lehetővé teszi az ügyfelek számára, hogy RESTful API-t használjanak szkriptelt interakciók létrehozására más alkalmazásokkal, ezáltal fejlett automatizálást érjenek el és kihasználják a meglévő infrastruktúrát.',
    'AdvancedSearchExtraDesc'             => 'A Speciális keresés Extra a felső sáv keresőmezőjét egyetlen kereséssé alakítja a kockázatok, keretrendszerek, kontrollok, dokumentumok, kivételek, tesztek, auditok, eszközök és eszközcsoportok között, egy teljes Keresés oldallal az eredmények átvizsgálásához. Csak azokat a rekordokat jeleníti meg, amelyeket a felhasználó láthat.',
    'AssessmentsExtraDesc'                => 'A Kockázatértékelés Extra lehetővé teszi a felhasználók számára kapcsolattartók meghatározását, kérdések létrehozását (logikával együtt), több kérdés összeállítását kérdőívsablonnal, kérdőívek létrehozását és kapcsolattartóknak küldését, a kérdőív eredményeinek megtekintését, az eredmények alapján kockázatok hozzáadását, az eredmények időbeli összehasonlítását, külsőleg testreszabott értékelések importálását és exportálását, valamint a kockázatértékelési auditnapló áttekintését.',
    'ActiveAssessmentsDesc'               => 'Jelenleg futó értékelések megtekintése és kezelése.',
    'WorkflowsExtraDesc'                  => 'A Workflows Extra egy vizuális, eseményvezérelt munkafolyamat-motort biztosít, amely automatizálja a kockázatkezelési műveleteket a SimpleRisk eseményeire válaszul. Olyan munkafolyamatokat tervezhet, amelyek változások – például egy kockázat beküldése, frissítése vagy felülvizsgálata – hatására aktiválódnak, így manuális beavatkozás nélkül továbbítják a jóváhagyásokat, kiosztják a feladatokat, és biztosítják a folyamatok folyamatosságát.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'A Secure Controls Framework (SCF) Extra közvetlen integráció a Secure Controls Framework és a SimpleRisk között. Importálja az SCF kontrollkatalógusát és azok leképezéseit a megfelelőségi és kiberbiztonsági keretrendszerek széles körére a SimpleRisk Governance funkciójába, így átveheti a szükséges keretrendszereket, és kezelheti azok kontrolljait anélkül, hogy kézzel kellene felépítenie őket.',

