    'EncryptionDeleteBackupBodyWhat'        => 'Az adatbázisban tárolt biztonsági mentés azonnal törlődik. Ezután már nem használhatja a Visszaállítás biztonsági mentésből funkciót az adatbázis titkosítás előtti állapotra való visszaállításához. Ha később problémát talál a titkosítással kapcsolatban, az egyetlen helyreállítási lehetőség az adatbázis újbóli visszaállítása az üzemi biztonsági mentésekből.',
