    'ApplicabilityErrNarrativeRequired' => 'A(z) \'{$state}\' állapothoz leírás szükséges.',
    'ApplicabilityErrNarrativeTooLong' => 'A leírás hosszabb, mint {$bytes} bájt.',
    'ApplicabilityErrReasonRequired' => 'Kizárási ok megadása szükséges egy kontroll nem alkalmazhatóként való megjelöléséhez.',
    'ApplicabilityErrProviderRequired' => 'Egy kontroll örököltként való megjelöléséhez szolgáltató szükséges.',
