    'BaseScoreExploitabilityMetrics' => 'Alap pontszám kihasználhatósági metrikái',
    'BaseScoreImpactMetrics' => 'Alappontszám hatásmutatói',
    // Per-field help popovers on the CVSS holder's 14 metric selects
    // (buildCvssScoreItem(), risk-details-form.js) -- one per CVSS v2
    // metric, matching the standard CVSS v2 specification definitions.
    // Double-quoted (not single-quoted, this file's usual style) so the
    // \n line breaks are real escape sequences: each popover leads with one
    // overall sentence, then one bullet line per option, rendered via
    // white-space: pre-line on .sr-scoring-help-popover .popover-body
    // (scss/modules/_questionnaire.scss) -- plain text throughout, no HTML,
    // so the popover stays initialized without Bootstrap's `html: true`.
    "AttackVectorHelp" => 'Hogyan lehet hozzáférni a sebezhetőséghez.
• Helyi: helyi hozzáférés szükséges, például konzolon vagy shellen keresztül.
• Szomszédos hálózat: a támadónak ugyanazon a fizikai vagy logikai hálózati szegmensen kell lennie.
• Hálózat: távolról, hálózaton keresztül kihasználható, helyi vagy szomszédos hozzáférés nélkül.',
    "AttackComplexityHelp" => 'Mennyire összetett a támadás, miután a támadó hozzáfér a célponthoz.
• Magas: speciális feltételek szükségesek, amelyeket nehéz megteremteni.
• Közepes: bizonyos feltételeknek teljesülniük kell, de ezek megléte esetén a kihasználás nem nehéz.
• Alacsony: nincs szükség különleges feltételekre.',
    "AuthenticationHelp" => 'Hányszor kell a támadónak hitelesítenie magát a célponton a kihasználáshoz.
• Többszörös: kétszer vagy többször szükséges hitelesítés, akár azonos hitelesítő adatokkal is.
• Egyszeri: egyszer szükséges hitelesítés.
• Nincs: nincs szükség hitelesítésre.',
    "ConfidentialityImpactHelp" => 'A kihasználás hatása a rendszer által feldolgozott adatok bizalmasságára.
• Nincs: nincs hatás.
• Részleges: bizonyos információk kiszivárognak, de a támadó nem szabályozza, hogy melyek, vagy a veszteség korlátozott.
• Teljes: a rendszeren lévő összes információ teljes kiszivárgása.',
    "IntegrityImpactHelp" => 'A kihasználás hatása a rendszer integritására.
• Nincs: nincs hatás.
• Részleges: egyes adatok módosíthatók, de a támadó nem szabályozza, hogy melyek, vagy a kör korlátozott.
• Teljes: a rendszer integritásának teljes sérülése; a támadó bármely fájlt módosíthatja.',
    "AvailabilityImpactHelp" => 'A kihasználás hatása a rendszer rendelkezésre állására.
• Nincs: nincs hatás.
• Részleges: csökkent teljesítmény vagy a rendelkezésre állás megszakadásai.
• Teljes: az érintett erőforrás teljes leállása.',
    "RemediationLevelHelp" => 'A sebezhetőséghez elérhető kezelés (remediáció) szintje.
• Hivatalos javítás: teljes körű gyártói megoldás elérhető.
• Ideiglenes javítás: hivatalos, de ideiglenes javítás elérhető.
• Kerülő megoldás: nem hivatalos, nem a gyártótól származó kerülő megoldás létezik.
• Nem elérhető: nincs megoldás, vagy egyik sem alkalmazható.',
    "ReportConfidenceHelp" => 'A sebezhetőség létezésébe vetett bizalom mértéke és műszaki részleteinek hitelessége.
• Meg nem erősített: egyetlen, meg nem erősített forrásból származó jelentés; az alapul szolgáló probléma feltételezés.
• Alátámasztatlan: több független forrás jelent azonos viselkedést, de a kiváltó ok nem megerősített.
• Megerősített: a gyártó elismerte a problémát, vagy forráskód- vagy exploitelemzés igazolta.',
    "CollateralDamagePotentialHelp" => "A sebezhetőség kihasználása esetén fennáll az életvesztés, a fizikai eszközök elvesztésének vagy a pénzügyi veszteség lehetősége.\n• Nincs: ilyen veszteség valószínűtlen.\n• Alacsonytól közepesig: mérsékelt veszteség lehetséges.\n• Magas: katasztrofális hatás a szervezet eszközeire, bevételére vagy biztonságára.",
    "TargetDistributionHelp" => 'A sebezhető rendszerek aránya a környezetben.
• Nincs: nem léteznek célrendszerek.
• Alacsony: a rendszerek 1–25%-a sebezhető.
• Közepes: 26–75%-uk sebezhető.
• Magas: 76–100%-uk sebezhető.',
    "ConfidentialityRequirementHelp" => 'Mennyire fontos az érintett eszköz bizalmassága a szervezet számára.
• Alacsony: a bizalmasság elvesztésének hatása korlátozott.
• Közepes: súlyos hatása van.
• Magas: katasztrofális hatása van.',
    "IntegrityRequirementHelp" => "Mennyire fontos az érintett eszköz integritása a szervezete számára.\n• Alacsony: az integritásvesztésnek korlátozott hatása van.\n• Közepes: súlyos hatása van.\n• Magas: katasztrofális hatása van.",
    "AvailabilityRequirementHelp" => "Mennyire fontos az érintett eszköz rendelkezésre állása a szervezete számára.\n• Alacsony: a rendelkezésre állási kiesésnek korlátozott hatása van.\n• Közepes: súlyos hatása van.\n• Magas: katasztrofális hatása van.",
    // Base Score Metrics' two sub-group intro sentences (metricsSubGroup()'s
    // `descKey`, risk-details-form.js) -- orient the user to what the GROUP
    // as a whole is asking, distinct from the per-field *Help popover keys
    // above which explain each metric's own options.
    'BaseScoreExploitabilityMetricsDescription' => 'Hogyan kellene egy támadónak elérnie és aktiválnia ezt a sebezhetőséget: hol kell lennie, mennyire összetett a támadás, és hogy először hitelesítenie kell-e magát.',
    'BaseScoreImpactMetricsDescription' => 'Mi történik, ha a sebezhetőséget sikeresen kihasználják: milyen hatással van az érintett rendszer bizalmasságára, integritására és rendelkezésre állására.',
    // Advanced Metrics' three optional sub-group intro sentences -- same
    // metricsSubGroup() `descKey` as the two Base Score groups above.
    'TemporalScoreMetricsDescription' => 'Hogyan változik idővel a sebezhetőség valós fenyegetése: az exploit kód jelenlegi állapota, milyen javítás érhető el, és mennyire megbízhatóak a jelentések arról, hogy létezik.',
    'EnvironmentalScoreMetricsDescription' => 'Hogyan függ a sebezhetőség kockázata a környezettől: a valós károkozás lehetősége, és rendszerei közül valójában hányat érint.',
    'ImpactSubscoreModifiersDescription' => 'Súlyozza az alap pontszám hatását azzal, hogy mennyire fontos a bizalmasság, az integritás és a rendelkezésre állás az adott eszköz esetében.',
    // Phase 4d-iii: DREAD holder help popovers (view_dread_help()'s
    // existing English text, includes/display.php, extracted to real $lang
    // keys -- that function's own content was raw hardcoded HTML, never
    // localized, so it could not be reused verbatim).
    'DamagePotentialHelp' => 'Mekkora kárt okoz, ha egy fenyegetést kihasználnak?' . "\n" . '0 = Semmi' . "\n" . '5 = Az egyéni felhasználói adatok veszélybe kerültek vagy érintettek.' . "\n" . '10 = Teljes rendszer- vagy adatmegsemmisítés',
    'ReproducibilityHelp' => 'Mennyire könnyű reprodukálni a fenyegetés kihasználását?
0 = Nagyon nehéz vagy lehetetlen, még az alkalmazás adminisztrátorai számára is.
5 = Egy-két lépés szükséges, esetleg jogosult felhasználónak kell lenni.
10 = Elég egy webböngésző és a címsor, hitelesítés nélkül.',
    'ExploitabilityHelp' => 'Mi szükséges e fenyegetés kihasználásához?
0 = Haladó programozási és hálózati ismeretek, egyéni vagy fejlett támadóeszközökkel.
5 = Az interneten létezik kártevő, vagy a kihasználás könnyen végrehajtható elérhető támadóeszközökkel.
10 = Elég egy webböngésző',
    'AffectedUsersHelp' => 'Hány felhasználót érint majd?' . "\n" . '0 = Nincs' . "\n" . '5 = Néhány felhasználó, de nem mindenki' . "\n" . '10 = Minden felhasználó',
    'DiscoverabilityHelp' => 'Mennyire könnyű felfedezni ezt a fenyegetést?
0 = Nagyon nehéz vagy lehetetlen; forráskód vagy adminisztrátori hozzáférés szükséges.
5 = Kitalálható tippeléssel vagy a hálózati forgalom megfigyelésével.
9 = Az ilyen hibák részletei már nyilvánosak, és keresőmotorral könnyen felfedezhetők.
10 = Az információ látható a webböngésző címsorában vagy egy űrlapon.',
    // The DREAD holder's summary card heading and "DREAD Metrics" card
    // heading. No existing key covers either (confirmed via grep before
    // adding).
    'DreadScore' => 'DREAD pontszám',
    'DreadMetrics' => 'DREAD metrikák',
    // Phase 4d-iv: OWASP holder help popovers (view_owasp_help()'s
    // existing English text, includes/display.php, extracted to real
    // $lang keys -- same never-localized-legacy-content extraction the
    // DREAD phase already did for its own 5 fields). Wording/levels
    // trued up against that function's real source text, not transcribed
    // from an earlier standard-methodology draft.
    'SkillLevelHelp' => 'Mennyire jártasak műszakilag a fenyegetést jelentő szereplők e csoportjának tagjai?
1 = Nincsenek műszaki ismeretek
3 = Némi műszaki ismeret
5 = Haladó számítógép-felhasználó
6 = Hálózati és programozási ismeretek
9 = Biztonsági behatolási ismeretek',
    'MotiveHelp' => 'Mennyire motiváltak a fenyegetést jelentő szereplők e csoportjának tagjai e sebezhetőség megtalálására és kihasználására?
1 = Alacsony vagy nulla haszon
4 = Lehetséges haszon
9 = Magas haszon',
    'OpportunityHelp' => 'Milyen erőforrások és lehetőségek szükségesek ahhoz, hogy a fenyegetést jelentő szereplők e csoportja megtalálja és kihasználja e sebezhetőséget?
0 = Teljes hozzáférés vagy drága erőforrások szükségesek
4 = Különleges hozzáférés vagy erőforrások szükségesek
7 = Némi hozzáférés vagy erőforrás szükséges
9 = Nincs szükség hozzáférésre vagy erőforrásra',
    'SizeHelp' => 'Mekkora a fenyegetést jelentő szereplők e csoportja?
2 = Fejlesztők
2 = Rendszeradminisztrátorok
4 = Intranet-felhasználók
5 = Partnerek
6 = Hitelesített felhasználók
9 = Névtelen internetes felhasználók',
    'EaseOfDiscoveryHelp' => 'Mennyire könnyű a fenyegetést jelentő szereplők e csoportjának felfedezni e sebezhetőséget?
1 = Gyakorlatilag lehetetlen
3 = Nehéz
7 = Könnyű
9 = Automatizált eszközök elérhetők',
    'EaseOfExploitHelp' => 'Mennyire könnyű a fenyegetést jelentő szereplők e csoportjának ténylegesen kihasználni e sebezhetőséget?
1 = Elméleti
3 = Nehéz
5 = Könnyű
9 = Automatizált eszközök elérhetők',
    'AwarenessHelp' => 'Mennyire ismert e sebezhetőség a fenyegetést jelentő szereplők e csoportja előtt?
1 = Ismeretlen
4 = Rejtett
6 = Nyilvánvaló
9 = Köztudott',
    'IntrusionDetectionHelp' => 'Mennyire valószínű, hogy a kihasználást észlelik?
1 = Aktív észlelés az alkalmazásban
3 = Naplózott és felülvizsgált
8 = Naplózott, felülvizsgálat nélkül
9 = Nem naplózott',
    'LossOfConfidentialityHelp' => 'Mennyi adat szivároghat ki, és mennyire érzékeny?
2 = Minimális, nem érzékeny adat szivárgott ki
6 = Minimális kritikus adat szivárgott ki
6 = Kiterjedt, nem érzékeny adat szivárgott ki
7 = Kiterjedt kritikus adat szivárgott ki
9 = Minden adat kiszivárgott',
    'LossOfIntegrityHelp' => 'Mennyi adat sérülhet, és mennyire súlyos a károsodás?
1 = Minimális, enyhén sérült adat
3 = Minimális, súlyosan sérült adat
5 = Kiterjedt, enyhén sérült adat
7 = Kiterjedt, súlyosan sérült adat
9 = Minden adat teljesen sérült',
    'LossOfAvailabilityHelp' => 'Mennyi szolgáltatás veszhet el, és mennyire létfontosságú?
1 = Minimális másodlagos szolgáltatás megszakadt
5 = Minimális elsődleges szolgáltatás megszakadt
5 = Kiterjedt másodlagos szolgáltatás megszakadt
7 = Kiterjedt elsődleges szolgáltatás megszakadt
9 = Minden szolgáltatás teljesen elveszett',
    'LossOfAccountabilityHelp' => 'Visszavezethetők-e a fenyegetést jelentő szereplők műveletei egy adott személyre?
1 = Teljesen visszavezethető
7 = Esetleg visszavezethető
9 = Teljesen névtelen',
    'FinancialDamageHelp' => 'Mekkora pénzügyi kárt okoz a kihasználás?
1 = Kevesebb, mint a sebezhetőség javításának költsége
3 = Csekély hatás az éves nyereségre
7 = Jelentős hatás az éves nyereségre
9 = Csőd',
    'ReputationDamageHelp' => 'Okozna-e a kihasználás az üzletet sértő hírnévkárosodást?
1 = Minimális kár
4 = Jelentős ügyfelek elvesztése
5 = A jóhírnév elvesztése
9 = Márkakárosodás',
    'NonComplianceHelp' => 'Mekkora kitettséget jelent a megfelelőség hiánya?
2 = Csekély szabálysértés
5 = Egyértelmű szabálysértés
7 = Nagy nyilvánosságot kapó szabálysértés',
    'PrivacyViolationHelp' => 'Mennyi személyazonosításra alkalmas információ hozható nyilvánosságra?' . "\n" . '3 = Egy személy' . "\n" . '5 = Több száz ember' . "\n" . '7 = Több ezer ember' . "\n" . '9 = Emberek milliói',
    // The OWASP holder's Score card heading. No existing key covers this
    // (confirmed via grep before adding) -- the Likelihood/Impact card
    // headings reuse the already-existing bare 'Likelihood'/'Impact' keys.
    'OwaspScore' => 'OWASP pontszám',
    // Phase 4d-iv follow-up: group-level descriptions for the 4 OWASP
    // subgroup headings, sourced from OWASP's own Risk Rating Methodology
    // (https://community.owasp.org/OWASP_Risk_Rating_Methodology), tightened
    // into short UI captions -- not a verbatim quote (see this task's own
    // source table for the original wording).
    'ThreatAgentFactorsDescription' => 'Megbecsüli a sikeres támadás valószínűségét a fenyegetést jelentő szereplők ezen csoportja részéről.',
    'VulnerabilityFactorsDescription' => 'Becsüli annak valószínűségét, hogy ezt a sebezhetőséget felfedezik és kihasználják.',
    'TechnicalImpactDescription' => 'A hatást bontja le bizalmasságra, integritásra, rendelkezésre állásra és elszámoltathatóságra.',
    'BusinessImpactDescription' => 'Azt tükrözi, ami az üzlet számára fontos, a nyers technikai hatáson túl.',
    // CVSS's own Temporal-metric 'Exploitability' help text. This key shares
    // a labelKey ('Exploitability') with DREAD's own field, so both would
    // otherwise derive the same generic lang key ('ExploitabilityHelp'),
    // with DREAD's entry silently winning for both -- risk-details-form.js's
    // buildCvssScoreItem() and risk-details-view.js's cvssMetricValueRow()
    // reference this key directly for CVSS's Exploitability field instead
    // of the generic '<labelKey>Help' derivation.
    'CVSSExploitabilityHelp' => 'A kihasználási technikák vagy a kód elérhetőségének jelenlegi állapota.
• Nem bizonyított: nem érhető el exploitkód, vagy a kihasználás elméleti.
• Proof-of-Concept: létezik exploitkód, de a legtöbb támadó számára nem praktikus.
• Működő: a működő exploitkód a legtöbb helyzetben működik.
• Magas: a kihasználás megbízható, és vagy automatizált (pl. féreg), vagy egyáltalán nem igényel exploitkódot.',
    // Risk Scoring -- Classic Inline (Task 3): the Classic scoring method's
    // new inline Score card heading and its Likelihood/Impact cards' short
    // plain-English descriptions (js/simplerisk/common/risk-details-form.js's
    // buildClassicHolder()). Deliberately NOT sourced from NIST SP 800-30 or
    // any other external standard -- confirmed with the user via the
    // approved mockup review, unlike OWASP's own subgroup descriptions
    // above, which do cite OWASP's Risk Rating Methodology.
    'ClassicScore' => 'Klasszikus pontszám',
    'ClassicLikelihoodDescription' => 'Mennyire valószínű, hogy ez a kockázat bekövetkezik.',
    'ClassicImpactDescription' => 'Milyen súlyos következményekkel járna, ha ez a kockázat bekövetkezne.',
    // Risk Scoring -- Custom Inline (Task 2): the Custom scoring method's
    // new inline Score card heading (js/simplerisk/common/risk-details-form.js's
    // buildCustomHolder()) and the Custom Value card's short description
    // caption. 'CustomValueDescription' text confirmed directly with the
    // user, same as Classic's own description keys above.
    'CustomScore' => 'Egyéni pontszám',
    'CustomValueDescription' => 'Az egyéni érték 0 és 10 közötti decimális érték lehet.',
    // Risk Scoring -- Contributing Risk Inline (Phase 4d-v): the last of
    // the three deferred scoring methods (DREAD/OWASP shipped earlier in
    // this same project). The Likelihood/Contributing Risk cards' short
    // plain-English descriptions (js/simplerisk/common/risk-details-form.js's
    // buildContributingRiskHolder()). The Score card heading reuses the
    // EXISTING 'ContributingRiskScore' key (already present above, same
    // text) rather than duplicating it -- 'ContributingRisk'/
    // 'ContributingLikelihood'/'Weight'/'Subject' are likewise reused as-is.
    'ContributingLikelihoodDescription' => 'Mennyire valószínű, hogy ez a kockázat bekövetkezik.',
    'ContributingRiskDescription' => 'Az alábbi tényezők mindegyike relatív fontosságával van súlyozva – válassza ki, hogy az egyes tényezők mennyire befolyásolják ezt a kockázatot.',
    // OWASP read-mode card (buildOwaspReadView(), risk-details-view.js):
    // the live calculation formula under each of the 4 sub-group names
    // (Threat Agent Factors/Vulnerability Factors/Technical Impact/
    // Business Impact), matching the legacy risk-scoring-details panel's
    // own "= ( a + b + c + d ) / 4" text (includes/display.php), and the
    // OWASP Risk Rating Methodology link note placed in the OWASP Score
    // column's open space below the summary numbers.
    'OwaspSubgroupFormula' => '= ( {a} + {b} + {c} + {d} ) / 4',
    'OwaspMethodologyNote' => 'Az OWASP kockázatértékelési módszertanának részletes leírása megtalálható a következő címen:',
    'Here' => 'itt',
    // Scoring widget formula captions (Classic/DREAD/Contributing Risk),
    // the same ".sr-cvss-vector under the score label" treatment CVSS's
    // vector caption and OwaspSubgroupFormula above already have, on both
    // the edit-mode holder (risk-details-form.js) and the read-mode card
    // (risk-details-view.js). Classic reuses the existing RISKClassicExp1-5
    // keys instead of a new one -- see those keys' own long-standing
    // definitions above.
    'DreadScoreFormula' => '= ( {a} + {b} + {c} + {d} + {e} ) / 5',
    // Contributing Risk's per-factor weighted term and its shared
    // Likelihood term (update_contributing_risk_score(), includes/
    // functions.php) -- unlike DREAD/OWASP's fixed roster, the factor list
    // is admin-configured, so this is one formula PER FACTOR ROW rather
    // than one fixed caption under the total score.
    // {maxName}: score.php parity -- legacy's "Maximum Value" column showed
    // the max option's human-readable name alongside its number (e.g.
    // "[5] Certain", includes/display.php); these formulas only showed the
